/* Original diagrams; sources, numeric derivations and limitations in visual-lab/metabolic-disease/learning-card.md. */
import type React from "react";
import { BLUE, GREEN, INK, MUTED, ORANGE, He as StandardHe, La } from "./biochemFigures";
const RED="#b91c1c", TEAL="#0f766e", PURPLE="#7c3aed", LINE="#cbd5e1";
function He(p:React.ComponentProps<typeof StandardHe>){if(typeof p.children==="string"&&!/[\u0590-\u05ff]/.test(p.children))return <La {...p}/>;const c=typeof p.children==="string"?p.children.replace(/→/g,"←").replace(/([A-Za-z][A-Za-z0-9_α-ωΑ-Ω²³⁺⁻′–−/.-]*(?:[ \t]+[A-Za-z][A-Za-z0-9_α-ωΑ-Ω²³⁺⁻′–−/.-]*)*)/g,"\u2066$1\u2069"):p.children;return <StandardHe {...p}>{c}</StandardHe>;}
function Fig({h,label,children}:{h:number;label:string;children:React.ReactNode}){return <svg viewBox={`0 0 480 ${h+40}`} className="w-full h-auto" role="img" aria-label={label}><title>{label}</title>{children}<He x={240} y={h+24} size={14} color={MUTED}>סכמה, לא בקנה מידה · חץ: הפעלה / זרימה · ⊣: עיכוב</He></svg>;}
function Panel({y,h,title,color=BLUE,children}:{y:number;h:number;title:string;color?:string;children:React.ReactNode}){return <g transform={`translate(0 ${y})`}><rect x={12} width={456} height={h} rx={14} fill="#f8fafc" stroke={LINE}/><rect x={449} y={15} width={5} height={22} rx={2} fill={color}/><He x={431} y={32} anchor="end" size={18} bold color={color}>{title}</He>{children}</g>;}
function Arrow({x1,y1,x2,y2,color=INK,stop=false,dash=false}:{x1:number;y1:number;x2:number;y2:number;color?:string;stop?:boolean;dash?:boolean}){const a=Math.atan2(y2-y1,x2-x1),s=Math.sin(a),c=Math.cos(a);return <g><line x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth={1.8} strokeDasharray={dash?"4 3":undefined}/>{stop?<line x1={x2-s*6} y1={y2+c*6} x2={x2+s*6} y2={y2-c*6} stroke={color} strokeWidth={2.5}/>:<path d={`M${x2-8*c+4*s} ${y2-8*s-4*c} L${x2} ${y2} L${x2-8*c-4*s} ${y2-8*s+4*c}`} fill="none" stroke={color} strokeWidth={1.8}/>}</g>;}
function Box({x,y,w=160,text,sub,color=BLUE,he=false}:{x:number;y:number;w?:number;text:string;sub?:string;color?:string;he?:boolean}){return <g><rect x={x} y={y} width={w} height={sub?64:40} rx={10} fill="white" stroke={color} strokeWidth={1.5}/>{(he||/[\u0590-\u05ff]/.test(text))?<He x={x+w/2} y={y+26} size={17} bold color={color}>{text}</He>:<La x={x+w/2} y={y+26} size={17} bold color={color}>{text}</La>}{sub&&<He x={x+w/2} y={y+51} size={15}>{sub}</He>}</g>;}
function Note({y,children,color=MUTED}:{y:number;children:string;color?:string}){return <He x={240} y={y} size={16} color={color}>{children}</He>;}
function Membrane({y,x=32,w=416}:{y:number;x?:number;w?:number}){return <g>{[0,10].map(d=><g key={d}>{Array.from({length:Math.floor(w/11)},(_,i)=><g key={i}><circle cx={x+i*11+5} cy={y+d} r={3} fill={TEAL}/><line x1={x+i*11+5} y1={y+d+(d?-2:2)} x2={x+i*11+5} y2={y+5} stroke={TEAL}/></g>)}</g>)}</g>;}
function Receptor({x,y,color=BLUE}:{x:number;y:number;color?:string}){return <path d={`M${x-12} ${y-22} v12 q0 10 12 10 q12 0 12-10 v-12 M${x} ${y} v31`} fill="none" stroke={color} strokeWidth={6} strokeLinecap="round"/>;}
function Mito({x,y,bad=false}:{x:number;y:number;bad?:boolean}){return <g transform={`translate(${x} ${y})`}><rect width={bad?76:65} height={bad?46:32} rx={20} fill="#fff7ed" stroke={ORANGE} strokeWidth={2}/><path d={bad?"M12 22 Q28 0 35 28 L55 13":"M10 18 Q17 3 23 19 T36 18 T49 18 L55 13"} stroke={ORANGE} strokeWidth={2} fill="none"/></g>;}
function Adipose({x,y,r=31}:{x:number;y:number;r?:number}){return <g transform={`translate(${x} ${y})`}><circle r={r} fill="#fffbeb" stroke={ORANGE} strokeWidth={1.7}/><circle cy={-r*.12} r={r*.77} fill="#fde68a" stroke="#eab308"/><ellipse cx={-r*.25} cy={r*.79} rx={r*.25} ry={r*.12} fill={PURPLE}/></g>;}
function Organ({x,y,kind}:{x:number;y:number;kind:"liver"|"muscle"|"brain"|"gut"|"kidney"}){return <g transform={`translate(${x} ${y})`}>{kind==="liver"?<g><path d="M-43 -15 Q-15 -35 43 -18 L29 7 Q5 32-29 25 Q-44 14-43-15Z" fill="#fed7aa" stroke={ORANGE} strokeWidth={2}/><path d="M10 -20 L0 14" stroke={ORANGE} fill="none"/></g>:kind==="muscle"?<g><path d="M-45 0 Q0-36 45 0 Q0 36-45 0Z" fill="#fee2e2" stroke={RED} strokeWidth={2}/>{[-20,-10,0,10,20].map(a=><path key={a} d={`M${a} -11 v22`} stroke={RED} opacity={.6}/>)}</g>:kind==="brain"?<g><path d="M-35 17 C-65-7-30-43-7-26 C15-43 58-18 37 15 Q15 37-5 23 Q-22 37-35 17Z" fill="#ede9fe" stroke={PURPLE} strokeWidth={2}/><path d="M-21-17 Q0-8-20 8 M5-20 Q29-12 11 6 M-4-9 Q-16 21 16 19" fill="none" stroke={PURPLE}/></g>:kind==="kidney"?<path d="M10-28 C-45-40-50 40 4 29 Q29 22 7 7 Q-5-2 13-10 Q28-20 10-28Z" fill="#fecaca" stroke={RED} strokeWidth={2}/>:<path d="M-33-24 H22 Q43-24 35-8 H-20 Q-39-8-31 7 H23 Q43 7 31 24 H-28" fill="none" stroke={TEAL} strokeWidth={10} strokeLinecap="round"/>}</g>;}
function Sarcomere({x,y,w=160,loose=false}:{x:number;y:number;w?:number;loose?:boolean}){return <g transform={`translate(${x} ${y})`}><path d={`M0-27 V27 M${w}-27 V27`} stroke={PURPLE} strokeWidth={5}/>{[-17,0,17].map(a=><g key={a}><path d={`M0 ${a} H${loose?w*.28:w*.42} M${w} ${a} H${loose?w*.72:w*.58}`} stroke={BLUE} strokeWidth={3}/><path d={`M${w*.31} ${a+5} H${w*.69}`} stroke={RED} strokeWidth={5}/></g>)}<path d={`M-8-34 Q${w/2}-47 ${w+8}-34 M-8 34 Q${w/2} 47 ${w+8} 34`} fill="none" stroke={TEAL} strokeWidth={2} strokeDasharray={loose?"6 8":undefined}/></g>;}
function Proteasome({x,y}:{x:number;y:number}){return <g transform={`translate(${x} ${y})`}><path d="M-27-25 Q0-40 27-25 V25 Q0 40-27 25Z" fill="#dbeafe" stroke={BLUE} strokeWidth={2}/><ellipse cy={-25} rx={27} ry={9} fill="#93c5fd" stroke={BLUE}/><ellipse cy={-25} rx={9} ry={4} fill="#1e3a8a"/>{[-10,0,10].map(a=><path key={a} d={`M-25 ${a} Q0 ${a+12}25 ${a}`} fill="none" stroke={BLUE}/>)}</g>;}
function Ub({x,y}:{x:number;y:number}){return <g>{[0,1,2].map(i=><circle key={i} cx={x+i*10} cy={y-i*8} r={5} fill={ORANGE}/>)}</g>;}
function ThreeTissues(){return <Fig h={670} label="מאגרי הכבד, שריר השלד ורקמת השומן ותפקידיהם בשובע ובצום">
 <Panel y={8} h={210} title="כבד — מווסת את הדלק בדם" color={ORANGE}><Organ x={80} y={89} kind="liver"/><He x={295} y={75} size={18} bold>גליקוגן: כ־100 גרם</He><He x={295} y={105} size={17}>G6Pase: שחרור גלוקוז</He><Note y={153}>שובע: גליקוגן, ליפוגנזה וייצוא VLDL</Note><Note y={183}>צום: גלוקוז וגופי קטון לדם</Note></Panel>
 <Panel y={230} h={210} title="שריר שלד — שימוש עצמי ומאגר חלבון" color={RED}><Organ x={80} y={89} kind="muscle"/><He x={295} y={75} size={18} bold>גליקוגן: כ־400 גרם + חלבון</He><He x={295} y={105} size={17}>אין G6Pase: אין ייצוא גלוקוז</He><Note y={153}>שובע: קליטת גלוקוז ובניית חלבון</Note><Note y={183}>צום: חמצון שומן ושחרור חומצות אמינו</Note></Panel>
 <Panel y={452} h={210} title="רקמת שומן — מאגר האנרגיה הגדול" color={TEAL}><Adipose x={80} y={90}/><He x={295} y={75} size={18} bold>טריגליצרידים (TG)</He><He x={295} y={105} size={17}>אין ייצוא גלוקוז</He><Note y={153}>שובע: קליטת חומצות שומן ואחסון</Note><Note y={183}>צום: שחרור חומצות שומן וגליצרול</Note></Panel>
 </Fig>;}
function InterorganFluxes(){const rows:[string,string,string,string][]=[
 ['כבד','גלוקוז','שריר · מוח · תאי דם',BLUE],['שריר / תאי דם','לקטט — מעגל קורי','כבד → גלוקוז',BLUE],['שומן','חומצות שומן (אלבומין)','כבד · שריר',ORANGE],['שומן','גליצרול','כבד → גלוקוז',ORANGE],['כבד','VLDL → LPL → חומצות שומן','שומן · שריר',TEAL],['מעי','כילומיקרונים → LPL → חומצות שומן','שומן · שריר',TEAL],['כבד','גופי קטון — בצום','מוח · שריר',PURPLE],['שריר','אלנין','כבד → גלוקוז + אוריאה',GREEN],['שריר','גלוטמין','מעי · כליה',GREEN],['כבד','אוריאה','כליה → שתן',MUTED]];return <Fig h={1000} label="מפת זרימות דלקים וחנקן בין האיברים; כל שורה מראה מקור, מטען ויעד">
 <Note y={27}>מקור בצד ימין · יעד משמאל · החץ מציין זרימת חומר</Note>{rows.map(([s,c,t,col],i)=>{const y=53+i*91;return <g key={c}><rect x={16} y={y} width={448} height={78} rx={12} fill={i%2?"#f8fafc":"#fff"}/><He x={240} y={y+22} size={17} bold color={col}>{c}</He><He x={406} y={y+57} size={16}>{s}</He><Arrow x1={354} y1={y+51} x2={277} y2={y+51} color={col}/><He x={155} y={y+57} size={16}>{t}</He></g>;})}<Note y={987}>החנקן נאסף בכבד; המעי מקבל גם חומצות אמינו מהמזון</Note></Fig>;}
function TissueHormones(){return <Fig h={660} label="הורמוני רקמת שומן, כבד ושריר; משמעות IL-6 תלויה במקור ובהקשר">
 <Panel y={8} h={300} title="רקמת שומן — מאגרים ואיכות הרקמה" color={ORANGE}><Adipose x={72} y={97}/><Box x={135} y={60} w={300} text="לפטין → מוח" sub="אות על מאגרים; פחות תיאבון" he color={ORANGE}/><Box x={39} y={142} w={396} text="אדיפונקטין → שריר וכבד" sub="רגישות לאינסולין · AMPK; יורד בהשמנה" he color={TEAL}/><Box x={39} y={221} w={396} text="TNF-α / IL-6 — דלקת כרונית" sub="פגיעה באיתות ברקמות מטבוליות" he color={RED}/></Panel>
 <Panel y={320} h={150} title="כבד — FGF21" color={BLUE}><Organ x={73} y={92} kind="liver"/><He x={293} y={83} size={18}>רקמת שומן ומוח</He><He x={293} y={116} size={16}>צום / עקה מטבולית</He></Panel>
 <Panel y={482} h={167} title="שריר מתכווץ — IL-6" color={GREEN}><Organ x={73} y={95} kind="muscle"/><He x={293} y={80} size={18}>כבד ושומן → שחרור דלק</He><He x={293} y={112} size={16}>עלייה בזמן פעילות גופנית</He><Note y={148}>אותה מולקולה, הקשר שונה מדלקת כרונית</Note></Panel></Fig>;}
function InsulinTargets(){const rows=[['שריר ושומן','AS160 → GLUT4','העברה לממברנה → קליטת גלוקוז',BLUE],['שריר וכבד','Akt ⊣ GSK3','גליקוגן סינתאז פעיל → גליקוגן',TEAL],['כבד','FoxO1 → מחוץ לגרעין','פחות PEPCK / G6Pase → פחות ייצור גלוקוז',ORANGE],['כבד','mTORC1 → SREBP-1c','יותר ליפוגנזה',ORANGE],['שומן','PDE3B → cAMP↓ → PKA↓','בלימת ליפוליזה',PURPLE],['שריר','mTORC1','חומצות אמינו + אינסולין → בניית חלבון',GREEN]];return <Fig h={785} label="ענפי IRS–PI3K–Akt לפי רקמה: גלוקוז, גליקוגן, שומן וחלבון">
 <La x={240} y={28} size={20} bold color={BLUE}>Insulin → IR → IRS → PI3K → Akt</La><Membrane y={58}/><Receptor x={240} y={58}/><Arrow x1={240} y1={99} x2={240} y2={121}/>{rows.map(([t,p,o,c],i)=><Panel key={p} y={133+i*106} h={96} title={t} color={c}><He x={240} y={57} size={18} color={c} bold>{p}</He><Note y={82}>{o}</Note></Panel>)}</Fig>;}
function AmpkMtor(){return <Fig h={565} label="מחסור מפעיל AMPK ואוטופגיה; שפע מפעיל mTORC1 ובנייה">
 <He x={122} y={28} bold size={18}>מחסור באנרגיה</He><He x={358} y={28} bold size={18}>שפע ואות גדילה</He><La x={122} y={60} size={17}>AMP / ADP + LKB1</La><He x={358} y={60} size={17}>לאוצין + Akt</He><Arrow x1={122} y1={75} x2={122} y2={101} color={TEAL}/><Arrow x1={358} y1={75} x2={358} y2={101} color={ORANGE}/><Box x={42} y={114} text="AMPK" color={TEAL}/><Box x={278} y={114} text="mTORC1" color={ORANGE}/><Arrow x1={213} y1={134} x2={266} y2={134} stop color={TEAL}/>
 <path d="M70 203 L411 171 M231 230 L252 195 L274 230Z" fill="#e2e8f0" stroke={MUTED} strokeWidth={3}/><Note y={261}>איזון בין שימוש באנרגיה לבנייה; לא מתג בינארי</Note>
 <Panel y={281} h={120} title="AMPK — שימור אנרגיה" color={TEAL}><La x={240} y={60} size={18}>AMPK ⊣ ACC · AMPK → ULK1</La><Note y={91}>פחות מלוניל-CoA · חמצון שומן ואוטופגיה עולים</Note></Panel>
 <Panel y={415} h={139} title="mTORC1 — השקעה בבנייה" color={ORANGE}><La x={240} y={59} size={18}>S6K · 4E-BP1 → protein synthesis</La><La x={240} y={90} size={18}>mTORC1 ⊣ ULK1</La><Note y={120}>אוטופגיה יורדת; סינתזת חלבון עולה</Note></Panel></Fig>;}
function ProteinBalance(){const rows=[['אחרי ארוחה','↑ בנייה','↓ פירוק','חיובי',GREEN],['צום לילה','↓ בנייה','↑ פירוק קל','שלילי קל',ORANGE],['כמה ימי צום','↓ בנייה','↑ פירוק','שלילי',RED],['שבועות צום','↓ בנייה','↓ פירוק שוב','שלילי מתון',TEAL]];return <Fig h={680} label="מאזן חלבון לפי מצב; אובדן חלבון בצום יורד מכ־75 לכ־20 גרם ליום">
 <Note y={28}>מאזן = סינתזה פחות פירוק; החצים איכותיים בלבד</Note>{rows.map(([t,s,b,n,c],i)=><Panel key={t} y={48+i*104} h={94} title={t} color={c}><He x={120} y={65} size={18}>{s}</He><He x={268} y={65} size={18}>{b}</He><He x={397} y={65} size={17} bold color={c}>{n}</He></Panel>)}
 <Panel y={476} h={190} title="חיסכון בחלבון — נתוני הקירוב שבטקסט" color={TEAL}><Note y={61}>אובדן חלבון, גרם ליום · לא קצב פירוק כולל</Note>{[75,20].map((v,i)=><g key={v}><He x={362} y={101+i*48} size={16}>{i?'שבועות צום':'ימים ראשונים'}</He><rect x={47} y={83+i*48} width={v*2.9} height={23} fill={i?TEAL:RED}/><La x={57+v*2.9} y={101+i*48} anchor="start" size={17}>{v}</La></g>)}</Panel></Fig>;}
function Clamp(){const subjects=[{n:'A',gir:10,hgp:0},{n:'B',gir:4,hgp:.5},{n:'C',gir:6,hgp:2.5}];return <Fig h={720} label="קלאמפ באינסולין קבוע ובגלוקוז 90 mg/dL; הזלפה ועוד ייצור כבדי שווים לקליטה">
 <Panel y={8} h={205} title="קלאמפ היפר־אינסולינמי אאוגליקמי"><Box x={31} y={61} w={185} text="אינסולין קבוע" he/><Box x={262} y={61} w={185} text="גלוקוז משתנה" he color={ORANGE}/><Arrow x1={124} y1={108} x2={190} y2={141}/><Arrow x1={355} y1={108} x2={289} y2={141} color={ORANGE}/><Box x={130} y={154} w={220} text="Blood glucose = 90 mg/dL" color={TEAL}/></Panel>
 <Panel y={225} h={476} title="נתוני התרגיל — שיווי משקל" color={TEAL}><La x={240} y={61} size={18} bold>GIR + HGP = uptake</La><Note y={90}>קצב: מ״ג לק״ג לדקה · אותו סולם לכל הנבדקים</Note>{subjects.map((s,i)=>{const y=123+i*95;return <g key={s.n}><La x={42} y={y+22} bold size={20}>{s.n}</La><rect x={76} y={y} width={s.gir*28} height={26} fill={BLUE}/><rect x={76+s.gir*28} y={y} width={s.hgp*28} height={26} fill={ORANGE}/><La x={424} y={y+21} size={18}>{s.gir+s.hgp}</La><La x={240} y={y+59} size={17}>{`${s.gir} + ${s.hgp} = ${s.gir+s.hgp}`}</La></g>;})}<rect x={100} y={411} width={18} height={12} fill={BLUE}/><He x={160} y={423} size={16}>הזלפה</He><rect x={265} y={411} width={18} height={12} fill={ORANGE}/><He x={350} y={423} size={16}>ייצור כבדי</He><Note y={456}>A רגיש · B בעיקר שריר · C בעיקר כבד</Note></Panel></Fig>;}
function DagPkc(){return <Fig h={655} label="מנגנונים מוצעים של DAG–PKC וקרמידים; השפעת שומן אקטופי תלויה במיקום ובסוג השומן">
 <Panel y={8} h={168} title="כבד — פגיעה בקולטן" color={ORANGE}><Membrane y={76}/><Receptor x={355} y={76}/><La x={115} y={69} size={19} bold color={ORANGE}>DAG → PKCε</La><Arrow x1={221} y1={90} x2={333} y2={90} stop color={RED}/><Note y={142}>קולטן אינסולין פחות פעיל → פחות Akt</Note></Panel>
 <Panel y={188} h={139} title="שריר — פגיעה באיתות ובהובלה" color={RED}><La x={240} y={70} size={20}>DAG → PKCθ ⊣ insulin signaling</La><Note y={108}>פחות העברת GLUT4 לממברנה</Note></Panel>
 <Panel y={339} h={139} title="קרמידים — התכנסות על Akt" color={PURPLE}><La x={240} y={70} size={20}>Ceramide → PP2A / PKCζ ⊣ Akt</La><Note y={108}>מסלול נוסף; אינו זהה למסלול DAG</Note></Panel>
 <Panel y={490} h={153} title="ליפודיסטרופיה — אין מחסן בטוח" color={TEAL}><Adipose x={72} y={92}/><path d="M45 65 L98 117 M98 65 L45 117" stroke={RED} strokeWidth={3}/><Arrow x1={123} y1={92} x2={187} y2={92} color={ORANGE}/><He x={309} y={85} size={18}>שומן מצטבר בכבד ובשריר</He><He x={309} y={116} size={16}>תנגודת קשה גם בלי השמנה</He></Panel></Fig>;}
